/* com.portal.user.member.MberManageMapper.selectMberList */ SELECT uniqId, userTy, userId, userNm, emailAdres, areaNo, middleTelno, endTelno, moblphonNo, groupId, sttus, sbscrbDe FROM ( SELECT ESNTL_ID AS uniqId, 'USR01' AS userTy, MBER_ID AS userId, MBER_NM AS userNm, MBER_EMAIL_ADRES AS emailAdres, AREA_NO AS areaNo, MIDDLE_TELNO AS middleTelno, END_TELNO AS endTelno, MBTLNUM AS moblphonNo, GROUP_ID AS groupId, MBER_STTUS AS sttus, DATE_FORMAT(SBSCRB_DE, '%Y-%m-%d') AS sbscrbDe FROM LETTNGNRLMBER ) a WHERE 1 = 1
AND sttus LIKE #{sbscrbSttus}
AND userId LIKE CONCAT('%', #{searchKeyword}, '%')
AND userNm LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY sbscrbDe DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

/* com.portal.user.member.MberManageMapper.selectMberListTotCnt */ SELECT COUNT(1) AS totcnt FROM ( SELECT ESNTL_ID AS uniqId, 'USR01' AS userTy, MBER_ID AS userId, MBER_NM AS userNm, MBER_EMAIL_ADRES AS emailAdres, AREA_NO AS areaNo, MIDDLE_TELNO AS middleTelno, END_TELNO AS endTelno, MBTLNUM AS moblphonNo, GROUP_ID AS groupId, MBER_STTUS AS sttus, SBSCRB_DE AS sbscrbDe FROM LETTNGNRLMBER ) a WHERE 1 = 1
AND sttus LIKE #{sbscrbSttus}
AND userId LIKE CONCAT('%', #{searchKeyword}, '%')
AND userNm LIKE CONCAT('%', #{searchKeyword}, '%')

