/* com.portal.user.member.MberManageMapper.selectPassword */
SELECT PASSWORD AS password
  FROM LETTNGNRLMBER
 WHERE ESNTL_ID = #{uniqId}

/* com.portal.user.member.MberManageMapper.checkIdDplct */
SELECT COUNT(1) AS usedCnt
  FROM (
       SELECT EMPLYR_ID       AS userId FROM LETTNEMPLYRINFO
        UNION ALL
       SELECT ENTRPRS_MBER_ID AS userId FROM LETTNENTRPRSMBER
        UNION ALL
       SELECT MBER_ID         AS userId FROM LETTNGNRLMBER
  ) a
 WHERE a.userId = #{checkId}
